dict(toc='The Constitution as a living document', id=45, title='THE CONSTITUTION AS A LIVING DOCUMENT · ARTICLE 21', part=0, icon='scale', prio='L',
 pyq=NOPYQ + 'pp. 13-15 · 2025 case: verify',
 simple='A living constitution evolves without losing its core identity. Know the seven features that make ours living, five reasons it must be, and the five-stage journey of Article 21 from Gopalan to digital access.',
 nodes=[
 sec('CONCEPT AND FEATURES', 'b'),
 bx('pk', 'The Indian Constitution is <b>not a frozen text</b>; it is a <b>living instrument with capabilities of enormous dynamism</b>. A living constitution <b>evolves with time without losing its core identity</b>: an ongoing project responding to social, economic and political realities.'),
 t('<b>What makes it living</b>',
   '<b>Article 368:</b> amendment power; over a hundred amendments since 1950',
   '<b>amendment procedures:</b> <b>simple majority, special majority, special majority with State ratification</b>: flexible yet stable; simple-majority changes are made <b>outside Article 368</b>',
   '<b>Basic Structure Doctrine:</b> <b>Kesavananda Bharati v. State of Kerala (1973)</b> keeps amendments within limits',
   '<b>Judicial Review:</b> supported by <b>Articles 13, 32, 136 and 226</b> (32 and 226 writ jurisdiction; 136 special leave to appeal)',
   '<b>open-textured language:</b> esp. <b>Articles 14, 19, 21</b>',
   '<b>Directive Principles:</b> guideposts to gradually realise socio-economic goals',
   '<b>constitutional conventions</b> develop over time'),
 OWN('ABJODDC', 'Seven features: <b>A</b>rt 368 · <b>B</b>asic structure · <b>J</b>udicial review · <b>O</b>pen texture · <b>D</b>PSP · <b>D</b>ifferent amendment procedures · <b>C</b>onventions.'),
 t('<b>Why it is necessary for India</b>',
   '<b>social:</b> gender equality, <b>LGBTQ rights</b>, dismantling caste hierarchies',
   '<b>economic:</b> <b>1991 liberalisation, privatisation, globalisation</b> forced reinterpretation of socialist provisions',
   '<b>technological:</b> internet, mobile, data, AI, digital identity raise questions on privacy, speech, surveillance',
   '<b>federal evolution:</b> coalition politics, <b>cooperative and competitive federalism</b>',
   '<b>global engagement:</b> treaties, climate agreements, human rights covenants'),
 OWN('SETFG', 'Five drivers: <b>S</b>ocial · <b>E</b>conomic · <b>T</b>echnological · <b>F</b>ederal · <b>G</b>lobal.'),
 bx('ye', '<b>Limit:</b> living does <b>not</b> mean it can mean anything anyone wants. It is bound by the <b>values of the Preamble, the limits of the Basic Structure and the discipline of constitutional methods</b>.'),
 sec('ARTICLE 21: THE LIVING CONSTITUTION IN ACTION', 'r'),
 tl(('1950', '<b>A. K. Gopalan:</b> narrow reading; restrictive <b>personal liberty</b>; rights as separate compartments; "<b>procedure established by law</b>" without fairness test'),
    ('1978', '<b>Maneka Gandhi:</b> progressive view; procedure must be <b>fair, just and reasonable</b>; opened a <b>whole new world of rights</b>'),
    ('PILs', 'unstated rights read into Art 21 (see list below)'),
    ('2017', '<b>Puttaswamy:</b> <b>nine-judge</b> bench, unanimous: <b>privacy intrinsic to life and liberty</b> (physical, informational, decisional); <b>overruled ADM Jabalpur (1976)</b>'),
    ('Now', 'dignity in death, partner choice, transgender rights, personality rights, digital access')),
 t('<b>Rights read into Article 21 (Stage 3)</b>',
   '<b>livelihood:</b> <i>Olga Tellis</i> (1985)', '<b>free legal aid:</b> <i>Hussainara Khatoon</i> (1979)', '<b>clean environment:</b> <i>M. C. Mehta</i> cases',
   '<b>education:</b> led to <b>Article 21A</b> by the <b>86th Amendment, 2002</b>', '<b>health:</b> <i>Paschim Banga Khet Mazdoor Samity</i>', '<b>shelter:</b> <i>Chameli Singh</i>',
   '<b>speedy trial</b> and protection against <b>custodial violence</b>'),
 OWN('L-FEEHSS', 'Stage-3 rights: <b>L</b>ivelihood (Olga Tellis) · <b>F</b>ree legal aid (Hussainara) · <b>E</b>nvironment (M. C. Mehta) · <b>E</b>ducation (21A) · <b>H</b>ealth (Paschim Banga) · <b>S</b>helter (Chameli Singh) · <b>S</b>peedy trial.'),
 t('<b>Stage 5: continuing expansion</b>',
   '<b>right to die with dignity</b> (passive euthanasia); <b>right to choose a partner</b>; <b>rights of transgender persons</b>; <b>personality rights</b> (e.g. <i>Jackie Shroff</i> case)',
   '<b>right to digital access:</b> <i>Pragya Prasun v. Union of India (2025)</i>: an <b>intrinsic component of the right to life and liberty under Article 21</b> (verify)'),
 sec('AMBEDKAR\'S INSIGHT', 'g'),
 bx('gr', 'The Constitution is <b>not a mere lawyer\'s document but a vehicle of life, and its spirit is the spirit of the age</b>. <b>"However good a Constitution may be, if those who are implementing it are bad, it will prove to be bad. However bad a Constitution may be, if those implementing it are good, it will prove to be good."</b> It lives only when <b>institutions and citizens give it life in every generation</b>.'),
 ],
 recall=[('Living constitution', 'evolves without losing core identity'), ('Limits on "living"', 'Preamble values, Basic Structure, constitutional methods'), ('Basic structure case', 'Kesavananda Bharati (1973)'), ('Judicial review articles', '13, 32, 136, 226'), ('Gopalan 1950 vs Maneka 1978', 'narrow vs fair, just, reasonable procedure'), ('Puttaswamy 2017', 'nine judges; privacy; overruled ADM Jabalpur'), ('Livelihood / legal aid cases', 'Olga Tellis / Hussainara Khatoon'), ('Art 21A inserted by', '86th Amendment, 2002'), ('Digital access case', 'Pragya Prasun v. Union of India (2025)')]),

